package com.gymflow.supplier;import com.gymflow.gym.Gym;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="suppliers",uniqueConstraints=@UniqueConstraint(name="uk_supplier_gym_name",columnNames={"gym_id","name"}))public class Supplier{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="gym_id",nullable=false)private Gym gym;@Column(nullable=false,length=120)private String name;@Column(length=180)private String email;@Column(length=30)private String phone;@Column(length=300)private String notes;@Column(nullable=false)private boolean active=true;protected Supplier(){}public Supplier(Gym gym,String name,String email,String phone,String notes){this.gym=gym;this.name=name;this.email=email;this.phone=phone;this.notes=notes;}public UUID getId(){return id;}public Gym getGym(){return gym;}public String getName(){return name;}public String getEmail(){return email;}public String getPhone(){return phone;}public String getNotes(){return notes;}public boolean isActive(){return active;}}
